board-cycle-step.code:
switch (phase) {
  case "FETCH":
  case "WAIT_FETCH":
    return "fetch";
  case "DECODE":
    return "decode";
  case "EXECUTE":
  case "WAIT_DATA":
    return "execute";
  default:
    return "idle";
}

board-draw-core.code:
const step = cycleStep(core.phase);
const steps: CycleStep[] = ["fetch", "decode", "execute"];
const fetched = fetchAddress(frame, core.id);
const title = `Core ${core.id}${core.inHandler ? " ⚡" : ""}${core.process ? ` · ${core.process}` : " · idle"}`;
// A short lane (many cores) gets one row: the name, then three small step boxes on the right.
if (rect.h < 14) {
  const boxW = 12;
  return (
    <g data-explain={explainCore(core)}>
      <Box rect={rect} fill={INK.white} width={1.2} />
      <Label x={rect.x + 2} y={rect.y + rect.h / 2} anchor="start" size={10.5} weight={700}>
        {title}
      </Label>
      {steps.map((name, i) => {
        const box = { x: rect.x + rect.w - (3 - i) * (boxW + 1) - 1, y: rect.y + 0.8, w: boxW, h: rect.h - 1.6 };
        return (
          <g key={name}>
            <Box rect={box} fill={step === name ? colour : INK.lightGrey} width={1} radius={1} explain={`${explainPhase(name)}${step === name ? ` ${explainCore(core)}` : ""}`} />
            <Label x={box.x + box.w / 2} y={box.y + box.h / 2} size={9} weight={step === name ? 700 : 400}>
              {name}
            </Label>
          </g>
        );
      })}
    </g>
  );
}
const stepW = (rect.w - 8) / 3;
return (
  <g data-explain={explainCore(core)}>
    <Box rect={rect} fill={INK.white} shadow={3} />
    <Label x={rect.x + 3} y={rect.y + 4} anchor="start" size={12} weight={700}>
      {title}
    </Label>
    {steps.map((name, i) => {
      const box = { x: rect.x + 2 + i * (stepW + 2), y: rect.y + 8, w: stepW, h: Math.max(6, rect.h - 16) };
      return (
        <g key={name}>
          <Box rect={box} fill={step === name ? colour : INK.lightGrey} width={step === name ? 2.2 : 1.2} explain={`${explainPhase(name)}${step === name ? ` ${explainCore(core)}` : ""}`} />
          <Label x={box.x + box.w / 2} y={box.y + box.h / 2} size={11} weight={step === name ? 700 : 500}>
            {name}
          </Label>
        </g>
      );
    })}
    <Label x={rect.x + 3} y={rect.y + rect.h - 3.5} anchor="start" size={10} weight={500}>
      {`PC ${hex(core.pc)}${core.instruction ? ` · ${core.instruction}` : ""}${fetched !== null ? ` · fetching ${hex(fetched)}` : ""}`}
    </Label>
  </g>
);

cpu-latch-reply.code:
if (message.replyTo === undefined) return;
const core = waiting.get(message.replyTo);
if (core === undefined) return;
waiting.delete(message.replyTo);
if (message.type === "mem.data") cpu = receiveReply(cpu, core, { type: "memData", bytes: message.payload.bytes });
else if (message.type === "mem.ack") cpu = receiveReply(cpu, core, { type: "memAck" });
else if (message.type === "fault" || message.type === "error") cpu = receiveReply(cpu, core, { type: "memFault", message: message.payload.message });

cpu-send-effects.code:
for (const effect of effects) {
  const id =
    effect.kind === "read"
      ? client.send("mem.read", "memory", { address: effect.address, length: effect.length })
      : client.send("mem.write", "memory", { address: effect.address, bytes: effect.bytes });
  waiting.set(id, effect.core);
}

fetch.code:
if (core.pc + INSTRUCTION_SIZE > MEMORY_SIZE) return faultWith(core, `PC ${hex(core.pc)} ran off the end of memory`);
return {
  core: moveTo(core, "WAIT_FETCH"),
  effects: [{ kind: "read", address: core.pc, length: INSTRUCTION_SIZE }],
};

await-instruction.code:
if (reply === null) return { core: { ...core, stalls: core.stalls + 1 }, effects: [] };
if (reply.type === "memFault") return faultWith(core, reply.message);
if (reply.type !== "memData") return faultWith(core, `expected instruction bytes, got ${reply.type}`);
return { core: moveTo(core, "DECODE", { ir: reply.bytes }), effects: [] };

decode-step.code:
if (core.ir.length !== INSTRUCTION_SIZE) return faultWith(core, `IR holds ${core.ir.length} bytes, not ${INSTRUCTION_SIZE}`);
const result = decode([core.ir[0], core.ir[1], core.ir[2], core.ir[3]]);
if (!result.ok) return faultWith(core, `at ${hex(core.pc)}: ${result.error}`);
return { core: moveTo(core, "EXECUTE", { instruction: result.instruction }), effects: [] };

execute-core.code:
case "LOAD":
  return { core: moveTo(core, "WAIT_DATA"), effects: [{ kind: "read", address: instruction.address, length: 1 }] };
case "ADD": {
  const sum = regs[instruction.reg] + regs[instruction.src];
  const result = sum & 0xff;
  return {
    core: finish(core, { registers: setRegister(core, instruction.reg, result), flags: { zero: result === 0, carry: sum > 0xff } }),
    effects: [],
  };
}
case "HALT":
  return { core: moveTo(core, "HALTED"), effects: [] };

execute-rest.code:
case "STORE":
  return {
    core: moveTo(core, "WAIT_DATA"),
    effects: [{ kind: "write", address: instruction.address, bytes: [regs[instruction.reg]] }],
  };
case "SUB": {
  const difference = regs[instruction.reg] - regs[instruction.src];
  const result = difference & 0xff;
  return {
    core: finish(core, { registers: setRegister(core, instruction.reg, result), flags: { zero: result === 0, carry: difference < 0 } }),
    effects: [],
  };
}
case "LOADI":
  return {
    core: finish(core, { registers: setRegister(core, instruction.reg, instruction.value), flags: { ...core.flags, zero: instruction.value === 0 } }),
    effects: [],
  };
case "JMP":
  return { core: finish(core, { pc: instruction.address }), effects: [] };
case "JZ":
case "JNZ": {
  const jump = instruction.op === "JZ" ? core.flags.zero : !core.flags.zero;
  return { core: jump ? finish(core, { pc: instruction.address }) : finish(core), effects: [] };
}

await-data.code:
if (reply === null) return { core: { ...core, stalls: core.stalls + 1 }, effects: [] };
if (reply.type === "memFault") return faultWith(core, reply.message);
const instruction = core.instruction;
if (instruction?.op === "LOAD" && reply.type === "memData") {
  const value = reply.bytes[0] ?? 0;
  return { core: finish(core, { registers: setRegister(core, instruction.reg, value), flags: { ...core.flags, zero: value === 0 } }), effects: [] };
}
if (instruction?.op === "STORE" && reply.type === "memAck") return { core: finish(core), effects: [] };
return faultWith(core, `unexpected ${reply.type} while waiting for ${instruction?.op ?? "nothing"}`);

switch-out.code:
const running = scheduler.processes.find((p) => p.core === core.id && p.state === "RUNNING");
if (!running) return { scheduler, core: clearCore(core) };
const saved: Process = {
  ...running,
  state: processFsm.go(running.state, state),
  context: saveContext(core),
  core: null,
  instructions: running.instructions + core.retired,
};
const others = scheduler.processes.filter((p) => p.pid !== running.pid);
return { scheduler: { ...scheduler, processes: [...others, saved] }, core: clearCore(core) };
